class Solution {
public:
    vector<int> maximumBeauty(vector<vector<int>>& items, vector<int>& queries) {
        sort(items.begin(), items.end());
        int n = items.size();
        for (int i = 1; i < n; i++) {
            items[i][1] = max(items[i][1], items[i - 1][1]);
        }
        int m = queries.size();
        vector<int> ans(m);
        for (int j = 0; j < m; j++) {
            int q = queries[j];
            int lo = 0, hi = n - 1, idx = -1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (items[mid][0] <= q) {
                    idx = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            ans[j] = (idx == -1) ? 0 : items[idx][1];
        }
        return ans;
    }
};
